local LuaTypeProviderFactory = require(script.Parent.Extensions.LuaTypeProviderFactory)
local InnerServices = require(script.Parent.InnerServices)
local Host = require(script.Parent.Host)
local FacadeFactory = require(script.Parent.FacadeFactory)

-- 继承 Core/Hosting/HostBuilder.lua

local HostBuilder = require(script.Parent.Core.Hosting.HostBuilder)

local TangSengHostBuilder = {}
setmetatable(TangSengHostBuilder, { __index = HostBuilder })

type TangSengInitConfigs = {
	manifestSource: Instance,
}

function validateConfigs(manifest: Instance)
	assert(manifest, "manifestSource is required")
	assert(manifest:IsA("Instance"), "manifestSource is not Instance")

	local luaTypeDefineSource = manifest.LuaTypes
	local tangsengFacadeSource = manifest.TangSengFacade

	assert(luaTypeDefineSource, "LuaTypeDefineSource is required")
	assert(luaTypeDefineSource:IsA("ModuleScript"), "LuaTypeDefineSource is not ModuleScript")
	assert(tangsengFacadeSource, "TangsengSource is required")
	assert(tangsengFacadeSource:IsA("ModuleScript"), "tangsengFacadeSource is not ModuleScript")
end

function TangSengHostBuilder.new(robloxManifest: IRobloxManifest?): ITangSengHostBuilder
	local manifest: IRobloxManifest = robloxManifest or game.ReplicatedStorage._robloxManifest
	validateConfigs(manifest)
	FacadeFactory.__SetFacadeSource(manifest.TangSengFacade)
	local luaTypeProvider = LuaTypeProviderFactory(manifest.LuaTypes)
	local self = HostBuilder.new(luaTypeProvider)
	setmetatable(self, { __index = TangSengHostBuilder })
	self.RobloxManifest = manifest
	return self
end

-- 配置应用配置文件夹，将该文件夹内所有的实例作为配置源，可以多次调用。可以指定一个反序列化函数，将实例反序列化为配置
-- @param folder Instance
-- @param deserializer ((data: any) -> {})?
function TangSengHostBuilder:ConfigureAppConfigurationFolder(folder: Instance, deserializer: ((data: any) -> {})?)
	local Helper = require(script.Parent.Extensions.HostBuilderHelper.ConfigureAppConfigurationFolder)
	self:ConfigureAppConfiguration(function(hostBuilderContext, configurationBuilder)
		Helper(folder, hostBuilderContext, configurationBuilder, deserializer)
	end)
	return self
end

function TangSengHostBuilder:Build(): IHost
	InnerServices.ConfigureServices(self)
	local coreHost = HostBuilder.Build(self)
	FacadeFactory.__SetRootFacadeServices(coreHost.Services)
	InnerServices.RequireServices(coreHost)
	local host = Host.new(coreHost)
	return host
end

return TangSengHostBuilder
